1	package com.maritime.platform.gateway.filter;
2	
3	import com.maritime.platform.gateway.security.GatewayPrincipal;
4	import com.maritime.platform.gateway.security.GatewayPrincipalHeaderCustomizer;
5	import com.maritime.platform.gateway.security.GatewaySecurityProperties;
6	
7	import org.springframework.beans.factory.annotation.Autowired;
8	import org.springframework.cloud.gateway.filter.GatewayFilterChain;
9	import org.springframework.cloud.gateway.filter.GlobalFilter;
10	import org.springframework.core.Ordered;
11	import org.springframework.core.annotation.Order;
12	import org.springframework.http.server.reactive.ServerHttpRequest;
13	import org.springframework.stereotype.Component;
14	import org.springframework.web.server.ServerWebExchange;
15	
16	import reactor.core.publisher.Mono;
17	
18	import java.util.LinkedHashSet;
19	import java.util.List;
20	import java.util.Set;
21	
22	/**
23	 * Injects verified identity headers into the downstream request after
24	 * authentication has completed.
25	 * <p>
26	 * Trusted headers are stripped earlier in the chain by
27	 * {@link UntrustedHeaderStripFilter}, so any headers written here are
28	 * guaranteed to originate from the gateway starter.
29	 */
30	@Component
31	@Order(GatewayFilterOrder.CONTEXT_HEADER_INJECTION)
32	public class ContextHeaderInjectionFilter implements GlobalFilter, Ordered {
33	
34		private final TrustedHeaderWriter trustedHeaderWriter;
35		private final List<GatewayPrincipalHeaderCustomizer> customizers;
36		private final GatewaySecurityProperties properties;
37	
38		/**
39		 * Default HMAC signature header names that must always be stripped
40		 * before forwarding, regardless of whether HMAC is enabled or how
41		 * headers are configured.
42		 */
43		static final Set<String> DEFAULT_HMAC_HEADERS = Set.of(
44				"X-App-Key", "X-Timestamp", "X-Nonce", "X-Body-Digest", "X-Signature");
45	
46		public ContextHeaderInjectionFilter(TrustedHeaderWriter trustedHeaderWriter,
47				GatewaySecurityProperties properties,
48				@Autowired(required = false) List<GatewayPrincipalHeaderCustomizer> customizers) {
49			this.trustedHeaderWriter = trustedHeaderWriter;
50			this.properties = properties;
51			this.customizers = customizers != null ? customizers : List.of();
52		}
53	
54		@Override
55		public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
56			ServerHttpRequest.Builder builder = exchange.getRequest().mutate();
57	
58			// Strip all known raw HMAC signature headers before forwarding.
59			// This runs unconditionally for all paths and auth modes, so
60			// raw signature material never reaches downstream even when
61			// hmac.enabled=false or the HMAC filter is absent.
62			Set<String> allHmacHeaders = allHmacHeaderNames();
63			if (!allHmacHeaders.isEmpty()) {
64				builder.headers(headers -> {
65					for (String h : allHmacHeaders) {
66						headers.remove(h);
67					}
68				});
69			}
70	
71			// Always write sanitized X-Trace-Id to downstream request.
72			// The client original was already captured by TraceIdGatewayFilter
73			// and stripped by UntrustedHeaderStripFilter, so this is the
74			// gateway-confirmed value for all paths (public, JWT, HMAC).
75			String traceId = exchange.getAttribute(TraceIdGatewayFilter.TRACE_ID_ATTR);
76			if (traceId != null) {
77				builder.header(TraceIdGatewayFilter.TRACE_ID_HEADER, traceId);
78			}
79	
80			GatewayPrincipal principal = exchange.getAttribute(GatewayPrincipal.ATTRIBUTE);
81			if (principal instanceof GatewayPrincipal.User user) {
82				trustedHeaderWriter.writeUserHeaders(builder, user);
83			} else if (principal instanceof GatewayPrincipal.App app) {
84				trustedHeaderWriter.writeAppHeaders(builder, app);
85			}
86	
87			if (principal != null) {
88				for (GatewayPrincipalHeaderCustomizer customizer : customizers) {
89					customizer.customize(builder, principal);
90				}
91			}
92	
93			ServerHttpRequest mutated = builder.build();
94			return chain.filter(exchange.mutate().request(mutated).build());
95		}
96	
97		/**
98		 * Returns the union of default and currently configured HMAC signature
99		 * header names. These are stripped unconditionally before forwarding.
100		 */
101		private Set<String> allHmacHeaderNames() {
102			Set<String> names = new LinkedHashSet<>(DEFAULT_HMAC_HEADERS);
103			if (properties != null) {
104				GatewaySecurityProperties.Headers hdrs = properties.getHmac().getHeaders();
105				names.add(hdrs.getAppKey());
106				names.add(hdrs.getTimestamp());
107				names.add(hdrs.getNonce());
108				names.add(hdrs.getBodyDigest());
109				names.add(hdrs.getSignature());
110			}
111			return names;
112		}
113	
114		@Override
115		public int getOrder() {
116			return GatewayFilterOrder.CONTEXT_HEADER_INJECTION;
117		}
118	}
