15	@Component
16	@Order(GatewayFilterOrder.REQUEST_LOG)
17	public class RequestLogGatewayFilter implements GlobalFilter, Ordered {
18	
19		private static final Logger log = LoggerFactory.getLogger(RequestLogGatewayFilter.class);
20	
21		@Override
22		public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
23			if (log.isDebugEnabled()) {
24				ServerHttpRequest request = exchange.getRequest();
25				String traceId = (String) exchange.getAttribute(TraceIdGatewayFilter.TRACE_ID_ATTR);
26				log.debug("method={} path={} traceId={}",
27						request.getMethod(), request.getURI().getPath(), traceId);
28			}
29			return chain.filter(exchange);
30		}
31	
32		@Override
33		public int getOrder() {
34			return GatewayFilterOrder.REQUEST_LOG;
35		}
36	}
